# Writes the upstream fix (projects/leptonica/arvo_23433/patch.diff @ 8365b29) to
# /output/fix.patch and the ground-truth PoC to /output/poc.bin.
set -euo pipefail

mkdir -p /output
base64 -d > /output/fix.patch <<'B64'
RnJvbSA4ZDZlMTc1NTUxOGNmYjk4NTM2ZDZjM2RhZjA2MDFmMjI2ZDE2ODQyIE1vbiBTZXAgMTcg
MDA6MDA6MDAgMjAwMQpGcm9tOiBEYW4gQmxvb21iZXJnIDxkYW4uYmxvb21iZXJnQGdtYWlsLmNv
bT4KRGF0ZTogU3VuLCAxNCBKdW4gMjAyMCAyMjo1Mjo0MCAtMDcwMApTdWJqZWN0OiBbUEFUQ0hd
IElzc3VlIDIzNDMzIGluIG9zcy1mdXp6OiBIZWFwLWJ1ZmZlci1vdmVyZmxvdyBpbgogZmluZE5l
eHRCb3JkZXJQaXhlbCgpICogQ2hlY2sgcGl4IGJvdW5kYXJ5IHdoZW4gbG9va2luZyBmb3IgdGhl
IG5leHQgcGl4ZWwuCgotLS0KIHNyYy9jY2JvcmQuYyB8IDIgKysKIDEgZmlsZSBjaGFuZ2VkLCAy
IGluc2VydGlvbnMoKykKCmRpZmYgLS1naXQgYS9zcmMvY2Nib3JkLmMgYi9zcmMvY2Nib3JkLmMK
aW5kZXggYzYyMzcwMi4uNGU2MzYzZSAxMDA2NDQKLS0tIGEvc3JjL2NjYm9yZC5jCisrKyBiL3Ny
Yy9jY2JvcmQuYwpAQCAtMTA4MCw2ICsxMDgwLDggQEAgbF91aW50MzIgICpsaW5lOwogICAgICAg
ICBwb3MgPSAocXBvcyArIGkpICUgODsKICAgICAgICAgbnB4ID0gcHggKyB4cG9zdGFiW3Bvc107
CiAgICAgICAgIG5weSA9IHB5ICsgeXBvc3RhYltwb3NdOworICAgICAgICBpZiAobnB4IDwgMCB8
fCBucHggPj0gdyB8fCBucHkgPCAwIHx8IG5weSA+PSBoKQorICAgICAgICAgICAgY29udGludWU7
CiAgICAgICAgIGxpbmUgPSBkYXRhICsgbnB5ICogd3BsOwogICAgICAgICB2YWwgPSBHRVRfREFU
QV9CSVQobGluZSwgbnB4KTsKICAgICAgICAgaWYgKHZhbCkgewotLSAKMi40My4yCgo=
B64

# The ground-truth PoC belongs to the gated HF dataset and is not redistributed in this
# repository; the task-server serves it to the oracle.
TS="${TASK_SERVER_URL:-http://task-server:9111}"
TS="${TS%/}"
for i in $(seq 1 30); do
  if curl -sf --max-time 60 -H "X-Submission-Token: 4b242d056304aaa514045bbbb4665ee7" "$TS/solve" > /output/poc.bin.part; then
    mv /output/poc.bin.part /output/poc.bin
    break
  fi
  [ "$i" -lt 30 ] || { echo "solve.sh: cannot fetch the ground-truth PoC from $TS" >&2; exit 1; }
  sleep 5
done

echo "solve.sh: wrote $(cd /output && ls | tr '\n' ' ')"
